wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only ids from a digest that actually went out are marked seen.
        // An unpublished digest leaves the store untouched so its items
        // remain eligible for the next run.
        if published.published {
            for id in published.considered.iter() {
                let key = format!("seen:{}", id);
                aap::caps::state_rw::put(&key, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
